<script setup lang="ts">
import { computed,ref } from 'vue'
import type { AlipayConfig,PaymentConfig,ZpayConfig } from '../../payments'
import Button from '../ui/Button.vue'
import ServicesPanel from './ServicesPanel.vue'
const props=defineProps<{config:PaymentConfig|AlipayConfig|ZpayConfig;channel:'wechat'|'alipay'|'zpay'}>(),emit=defineEmits<{edit:[]}>(),notice=ref('')
const rows=computed(()=>{const c=props.config;return 'mchId'in c?[['商户号 MchID',c.mchId],['AppID',c.appId],['商户证书序列号',c.merchantSerial],['微信支付公钥 ID',c.wechatPublicKeyId],['支付方式','Native 扫码支付']]:'sellerId'in c?[['收款商家 PID',c.sellerId],['支付宝 AppID',c.appId],['支付环境',c.gatewayUrl?c.gatewayUrl.includes('sandbox')?'沙箱环境':'正式环境':'未配置'],['网关地址',c.gatewayUrl]]:[['商户编号',c.pid],['下单地址',c.gatewayUrl],['订单查询地址',c.queryUrl],['指定渠道',c.cid],['支付方式',c.paymentType==='alipay'?'支付宝':'微信支付']]})
const keys=computed(()=>{const c=props.config;return 'hasMerchantKey'in c?c.hasMerchantKey:'hasAppPrivateKey'in c?c.hasAppPrivateKey&&c.hasAlipayPublicKey:c.hasMerchantPrivateKey&&c.hasApiV3Key&&c.hasWechatPublicKey})
const checks=computed(()=>{const c=props.config;return [{label:'商户与接口信息',ok:'mchId'in c?Boolean(c.mchId&&c.appId&&c.merchantSerial&&c.wechatPublicKeyId):'sellerId'in c?Boolean(c.appId&&c.sellerId&&c.gatewayUrl):Boolean(c.pid&&c.gatewayUrl&&c.queryUrl)},{label:'密钥配置',ok:keys.value},{label:'回调与返回地址',ok:Boolean(c.notifyUrl&&(!('returnUrl'in c)||c.returnUrl))}]})
async function copy(){try{await navigator.clipboard.writeText(props.config.notifyUrl);notice.value='回调地址已复制。'}catch{notice.value='复制失败，请手动选择地址复制。'}}
</script>
<template><div class="stack"><div class="form-grid"><section aria-label="支付配置概览"><div class="kv-grid"><div class="kv"><div class="kv-label">渠道状态</div><div class="kv-value">{{config.enabled?config.configured?'已启用':'已开启 · 配置不完整':'未启用'}}</div></div><div class="kv" v-for="[label,value] in rows" :key="label"><div class="kv-label">{{label}}</div><div class="kv-value">{{value||'未配置'}}</div></div><div class="kv"><div class="kv-label">支付密钥</div><div class="kv-value">{{keys?'已配置':'待完善'}}</div></div><div class="kv"><div class="kv-label">配置版本</div><div class="kv-value">{{config.version}}</div></div></div></section><section class="stack" aria-label="接入检查"><h3>接入检查</h3><p class="field-hint">根据已保存配置检查必填项</p><div class="kv-grid"><div class="kv" v-for="check in checks" :key="check.label"><div class="kv-label">{{check.label}}</div><div class="kv-value">{{check.ok?'已填写':'待完善'}}</div></div></div><p class="field-hint">{{config.configured?'渠道配置完整':'渠道配置尚未完整'}}。此检查不代表支付连通性验证。</p></section></div><section class="stack" aria-label="支付回调信息"><h3>回调信息</h3><p class="field-hint">支付完成后向此地址发送结果通知</p><code>{{config.notifyUrl||'尚未配置支付通知地址'}}</code><p v-if="'returnUrl'in config" class="field-hint">返回地址：{{config.returnUrl||'尚未配置'}}</p><div class="page-actions"><Button :disabled="!config.notifyUrl" icon="copy" @click="copy">复制</Button><Button variant="primary" @click="emit('edit')">编辑配置</Button></div><p v-if="notice" role="status">{{notice}}</p></section></div></template>
